static const long long MOD = 1000000007LL;

struct SegTree {
    int n;
    vector<long long> sum;
    vector<long long> mul;
    vector<long long> add;

    SegTree(int n_) : n(n_), sum(4 * n_, 0), mul(4 * n_, 1), add(4 * n_, 0) {}

    void build(int node, int l, int r, const vector<long long>& a) {
        if (l == r) {
            sum[node] = a[l] % MOD;
            if (sum[node] < 0) sum[node] += MOD;
            return;
        }
        int mid = (l + r) / 2;
        build(2 * node, l, mid, a);
        build(2 * node + 1, mid + 1, r, a);
        sum[node] = (sum[2 * node] + sum[2 * node + 1]) % MOD;
    }

    void apply(int node, int l, int r, long long m, long long a) {
        // Compose: existing (mul[node], add[node]) with new (m, a)
        // New state: (mul[node] * m mod MOD, (add[node] * m + a) mod MOD)
        mul[node] = (mul[node] * m) % MOD;
        add[node] = (add[node] * m + a) % MOD;
        if (add[node] < 0) add[node] += MOD;
        sum[node] = (sum[node] * m + a * (r - l + 1)) % MOD;
        if (sum[node] < 0) sum[node] += MOD;
    }

    void push(int node, int l, int r) {
        if (mul[node] != 1 || add[node] != 0) {
            int mid = (l + r) / 2;
            apply(2 * node, l, mid, mul[node], add[node]);
            apply(2 * node + 1, mid + 1, r, mul[node], add[node]);
            mul[node] = 1;
            add[node] = 0;
        }
    }

    void update(int node, int l, int r, int ql, int qr, long long m, long long a) {
        if (ql > r || qr < l) return;
        if (ql <= l && r <= qr) {
            apply(node, l, r, m, a);
            return;
        }
        push(node, l, r);
        int mid = (l + r) / 2;
        update(2 * node, l, mid, ql, qr, m, a);
        update(2 * node + 1, mid + 1, r, ql, qr, m, a);
        sum[node] = (sum[2 * node] + sum[2 * node + 1]) % MOD;
    }

    long long query(int node, int l, int r, int ql, int qr) {
        if (ql > r || qr < l) return 0;
        if (ql <= l && r <= qr) return sum[node];
        push(node, l, r);
        int mid = (l + r) / 2;
        return (query(2 * node, l, mid, ql, qr) + query(2 * node + 1, mid + 1, r, ql, qr)) % MOD;
    }
};

